begin;
select plan(12);
select has_function('public','create_profile_takeoff_draft','profile takeoff RPC exists');
set local role postgres;
insert into public.organization_members(organization_id,user_id,role) values('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000002','member') on conflict do nothing;
insert into public.material_products(id,organization_id,category,name,status,data_provenance) values('00000000-0000-4000-8000-000000000a52','00000000-0000-4000-8000-000000000010','sheet_metal','DEMO önálló lemez','active','demo');
insert into public.material_variants(id,organization_id,product_id,name,purchasing_unit,thickness_mm,technical_specs,source_name,data_provenance)
 values('00000000-0000-4000-8000-000000000a53','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000a52','DEMO m² lemez','square_meter',1,'{"profileMaterialSpec":"DEMO-A"}','DEMO paraméter','demo');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select lives_ok($$select * from public.save_standalone_profile_calculation('00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000a51','DEMO önálló profil','{"schemaVersion":"1.0.0","profileId":"00000000-0000-4000-8000-000000000a51","profileType":"l","label":"DEMO önálló profil","coordinateConvention":"x-right-y-up","dimensionConvention":"finished_tangent","thicknessMm":1,"straights":[{"id":"s1","tangentLengthMm":60},{"id":"s2","tangentLengthMm":40}],"bends":[{"id":"b1","signedTurnDeg":90,"insideRadiusMm":2,"allowance":{"mode":"explicit_ba","baMm":3,"source":{"kind":"user_provided","label":"DEMO BA"}}}],"formedRunLengthMm":2000,"pieceCount":3,"material":{"catalogVariantId":"00000000-0000-4000-8000-000000000a53","materialSpec":"DEMO-A","provenance":{"kind":"catalog_snapshot","label":"DEMO"}}}','{"schemaVersion":"1.0.0","bends":[{"id":"b1","allowanceMm":3}],"flatPattern":{"widthMm":103},"materialRequirement":{"totalNetBlankAreaSqM":0.618}}',0)$$,'independent profile revision saved without project');
select lives_ok($$select * from public.create_profile_takeoff_draft('00000000-0000-4000-8000-000000000010',null,'00000000-0000-4000-8000-000000000a51',(select current_revision_id from public.calculations where id='00000000-0000-4000-8000-000000000a51'),'00000000-0000-4000-8000-000000000a53','DEMO önálló piszkozat','00000000-0000-4000-8000-000000000a54')$$,'project-less takeoff draft is created');
select is((select count(*)::int from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000a54' and project_id is null and created_by='00000000-0000-4000-8000-000000000001'),1,'draft has no project and records its creator');
select is((select final_quantity from public.material_takeoff_items where takeoff_id=(select id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000a54')),0.618::numeric,'net area 0.618 m² from the saved revision');
select is((select source_calculation_revision_id from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000a54'),(select current_revision_id from public.calculations where id='00000000-0000-4000-8000-000000000a51'),'exact saved source revision is referenced');
select is((select draft_created from public.create_profile_takeoff_draft('00000000-0000-4000-8000-000000000010',null,'00000000-0000-4000-8000-000000000a51',(select current_revision_id from public.calculations where id='00000000-0000-4000-8000-000000000a51'),'00000000-0000-4000-8000-000000000a53','DEMO önálló piszkozat','00000000-0000-4000-8000-000000000a54')),false,'same key and payload is idempotent');
select throws_ok($$select * from public.create_profile_takeoff_draft('00000000-0000-4000-8000-000000000010',null,'00000000-0000-4000-8000-000000000a51',(select current_revision_id from public.calculations where id='00000000-0000-4000-8000-000000000a51'),'00000000-0000-4000-8000-000000000a53','más név','00000000-0000-4000-8000-000000000a54')$$,'22023',null,'same key with a different payload is rejected');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.material_takeoffs where transfer_request_key='00000000-0000-4000-8000-000000000a54'),0,'another member cannot read the private draft');
select is((select count(*)::int from public.material_takeoff_items),0,'another member cannot read its items');
select throws_ok($$select * from public.create_profile_takeoff_draft('00000000-0000-4000-8000-000000000010',null,'00000000-0000-4000-8000-000000000a51',(select current_revision_id from public.calculations where id='00000000-0000-4000-8000-000000000a51'),'00000000-0000-4000-8000-000000000a53','idegen forrás','00000000-0000-4000-8000-000000000a55')$$,'P0002',null,'another member cannot transfer a private profile');
select is((select count(*)::int from public.material_takeoffs where project_id is null and created_by='00000000-0000-4000-8000-000000000002'),0,'rejected transfer left no draft behind');
select * from finish();
rollback;
